public static ListNode computeIterative(ListNode head) {
    ListNode prev = null;
    ListNode curr = head;

    while (curr != null) {
        ListNode next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

public static ListNode computeRecursive(ListNode head) {
    if (head == null || head.next == null) {
        return head;
    }

    ListNode reversed = computeRecursive(head.next);
    head.next.next = head;
    head.next = null;
    return reversed;
}

public static ListNode computeWithStack(ListNode head) {
    if (head == null || head.next == null) {
        return head;
    }

    java.util.Stack<ListNode> stack = new java.util.Stack<>();
    ListNode curr = head;
    while (curr != null) {
        stack.push(curr);
        curr = curr.next;
    }

    ListNode newHead = stack.pop();
    curr = newHead;
    while (!stack.isEmpty()) {
        curr.next = stack.pop();
        curr = curr.next;
    }
    curr.next = null;
    return newHead;
}
